 <?php foreach($data->journey_plans as $plan): $content=json_decode($plan['content']??'{}',true)?:[]; ?><details class="fj-history"><summary><?= $h($plan['month']) ?> · <?= $h(fcc_partner_goals()[$plan['goal']]??fcc_t('Raniji plan')) ?></summary><p><?= $h($content['summary']??'') ?></p><?php foreach($content['weeks']??[] as $week): ?><h3><?= $h($week['title']??'') ?></h3><p><?= $h($week['action']??'') ?></p><small><?= $h($week['measure']??'') ?></small><?php endforeach ?><p><?= $h($content['next_step']??'') ?></p></details><?php endforeach ?>
