 <?php foreach(fcc_localize_copy(['leader_ai_weekly_plans'=>fcc_t('Raniji AI prijedlog'),'leader_ai_weekly_checkins'=>fcc_t('Raniji tjedni osvrt'),'leader_ai_weekly_outcomes'=>fcc_t('Raniji zabilježeni ishod')]) as $key=>$label): foreach(array_slice((array)($j['user']->preferences->$key??[]),0,50) as $old): ?><details class="fj-history"><summary><?= $label ?> · <?= $h(((array)$old)['generated_at']??((array)$old)['submitted_at']??'') ?></summary><?php $print=function($value,$depth=0)use(&$print,$h){if($depth>6)return;if(is_scalar($value)&&!is_bool($value)){echo '<p>'.$h($value).'</p>';}elseif(is_array($value)||is_object($value))foreach((array)$value as $k=>$child){if(in_array($k,['id','user_id','request_key','model'],true))continue;$print($child,$depth+1);}};$print($old); ?></details><?php endforeach; endforeach ?>
 <?php if(!$data->journey_plans&&!$data->journey_reviews): ?><p class="fp-muted"><?= htmlspecialchars(fcc_t('Novi planovi i osvrti ovdje se pojavljuju tek kada ih spremiš.'), ENT_QUOTES, 'UTF-8') ?></p><?php endif ?>
